SELECT p.id, p.slug, c.iso_code, p.language, f.id AS feed_id FROM publishers p JOIN countries c ON c.id = p.country_id
  JOIN feeds f ON f.publisher_id = p.id WHERE p.slug IN ('asharq-al-awsat','asharq-al-awsat-english','aden-al-ghad','globes','reporter-lu','berlingske','information-dk','altinget','err-ee','aripaev','plusinfo','radio-mof','the-shift-news','faz','die-presse','kurier','rts-info','aftonbladet','expressen','the-irish-times','seznam-zpravy','denik-n','pravda-sk','teraz-tasr','philenews','politis-cy','verslo-zinios','diena','la-lv','b92','vreme','prishtina-insight','balkanweb','abc-news-albania') ORDER BY p.id;
SELECT p.slug, e.classification_tags, left(e.historical_context, 60) FROM editorial_profiles e JOIN publishers p ON p.id = e.publisher_id
  WHERE p.slug IN ('asharq-al-awsat', 'err-ee', 'teraz-tasr') ORDER BY 1;
COMMIT;
